import Layout from "./layout/Layout";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Grid from "@mui/material/Grid2";
import Stack from "@mui/material/Stack";
import Step from "@mui/material/Step";
import StepLabel from "@mui/material/StepLabel";
import Stepper from "@mui/material/Stepper";
import Typography from "@mui/material/Typography";
import ChevronLeftRoundedIcon from "@mui/icons-material/ChevronLeftRounded";
import ChevronRightRoundedIcon from "@mui/icons-material/ChevronRightRounded";
import AddressForm from "./checkout/AddressForm";
import Review from "./checkout/Review";
import { useDispatch, useSelector } from "react-redux";
import { useCreateOrderMutation } from "../redux/slices/orderSlice";
import { toast } from "react-toastify";
import { clearCart } from "../redux/slices/cartSlice";
import axios from "axios";
import React from "react";
import { Link } from "react-router-dom";

const steps = ["Sign In", "Shipping address", "Review your order"];
function getStepContent(step) {
  switch (step) {
    case 0:
      return;
    case 1:
      return <AddressForm step={step} />;
    case 2:
      return <Review />;
    default:
      throw new Error("Unknown step");
  }
}

export default function Checkout(props) {
  const dispatch = useDispatch();
  const [createOrder] = useCreateOrderMutation();
  const [activeStep, setActiveStep] = React.useState(1);
  const cart = useSelector((state) => state.cart);
  const { shippingAddress, cartItems } = cart;
  console.log("cart", cart);
  console.log("active step", activeStep);

  React.useEffect(() => {
    // Check to see if this is a redirect back from Checkout
    const query = new URLSearchParams(window.location.search);

    if (query.get("success")) {
      if (cartItems?.length > 0) {
        setActiveStep(3);
        // eslint-disable-next-line
        const res = createOrder({
          ...cart,
          orderItems: cart.cartItems,
        }).unwrap();

        dispatch(clearCart());
        toast("Order generated successfully!");
      }
    }

    if (query.get("canceled")) {
      toast.error(
        "Order canceled -- continue to shop around and checkout when you're ready.",
      );
    }
  }, [dispatch]);

  const handleNext = () => {
    setActiveStep(activeStep + 1);
  };

  const handleBack = () => {
    setActiveStep(activeStep - 1);
  };

  //payment
  const handlePayment = async () => {
    try {
      const payment = await axios.post("/api/payment/create", cart);
      if (payment.status === 200) {
        window.location.href = payment.data.url;
      }
      if (payment.success == false) {
        toast.error("Please login to continue");
      }
      console.log("test payment", payment);
    } catch (error) {
      toast.error(error?.errors?.map((err) => err?.message)?.join(", "));
      console.log(error?.errors?.map((err) => err?.message)?.join(", "));
    }
  };
  return (
    <>
      <Layout>
        <Box sx={{ minHeight: "100vh" }}>
          <Grid
            container
            sx={{
              height: {
                xs: "100%",
              },
              mt: {
                xs: 4,
                sm: 0,
              },
            }}
          >
            {/* stepper */}
            <Grid
              sx={{
                display: "flex",
                flexDirection: "column",
                maxWidth: "100%",
                width: { xs: "100%", sm: "60%", xl: "45%" },
                margin: "auto",
                backgroundColor: {
                  xs: "transparent",
                  sm: "background.default",
                },
                alignItems: "start",
                pt: { xs: 0, sm: 16 },
                px: { xs: 2, sm: 10 },
                gap: { xs: 4, md: 8 },
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  justifyContent: { sm: "space-between", md: "flex-end" },
                  alignItems: "center",
                  width: "100%",
                }}
              >
                <Box
                  sx={{
                    display: { xs: "none", md: "flex" },
                    flexDirection: "column",
                    justifyContent: "space-between",
                    alignItems: "flex-end",
                    flexGrow: 1,
                  }}
                >
                  <Stepper
                    id="desktop-stepper"
                    activeStep={activeStep}
                    sx={{ width: "100%", height: 40 }}
                  >
                    {steps.map((label) => (
                      <Step
                        sx={{
                          ":first-of-type": { pl: 0 },
                          ":last-child": { pr: 0 },
                        }}
                        key={label}
                      >
                        <StepLabel>{label}</StepLabel>
                      </Step>
                    ))}
                  </Stepper>
                </Box>
              </Box>

              <Box
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  flexGrow: 1,
                  width: "100%",
                  maxHeight: "720px",
                  gap: { xs: 5, md: "none" },
                }}
              >
                {/* mobile stepper */}
                <Stepper
                  id="mobile-stepper"
                  activeStep={activeStep}
                  alternativeLabel
                  sx={{ display: { sm: "flex", md: "none" }, pt: 2 }}
                >
                  {steps.map((label) => (
                    <Step
                      sx={{
                        ":first-of-type": { pl: 0 },
                        ":last-child": { pr: 0 },
                        "& .MuiStepConnector-root": {
                          top: { xs: 6, sm: 12 },
                        },
                      }}
                      key={label}
                    >
                      <StepLabel
                        sx={{
                          ".MuiStepLabel-labelContainer": {
                            maxWidth: "70px",
                          },
                        }}
                      >
                        {label}
                      </StepLabel>
                    </Step>
                  ))}
                </Stepper>
                {/* mobile stepper */}
                {activeStep === steps.length ? (
                  <Stack spacing={2} useFlexGap>
                    <Typography variant="h1">📦</Typography>
                    <Typography variant="h5">
                      Thank you for your order!
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{ color: "text.secondary" }}
                    >
                      Your order number is
                      <strong>&nbsp;#140396</strong>. We have emailed your order
                      confirmation and will update you once its shipped.
                    </Typography>
                    <Button
                      variant="contained"
                      sx={{
                        alignSelf: "start",
                        width: { xs: "100%", sm: "auto" },
                      }}
                    >
                      <Link
                        style={{ textDecoration: "none", color: "white" }}
                        to="/user/orders"
                      >
                        Go to my orders
                      </Link>
                    </Button>
                  </Stack>
                ) : (
                  <React.Fragment>
                    {getStepContent(activeStep)}
                    <Box
                      sx={[
                        {
                          display: "flex",
                          flexDirection: { xs: "column-reverse", sm: "row" },
                          alignItems: "end",
                          flexGrow: 1,
                          gap: 1,
                          pb: { xs: 12, sm: 0 },
                          mt: { xs: 2, sm: 0 },
                          mb: "60px",
                        },
                        activeStep !== 1
                          ? { justifyContent: "space-between" }
                          : { justifyContent: "flex-end" },
                      ]}
                    >
                      {activeStep !== 1 && (
                        <Button
                          startIcon={<ChevronLeftRoundedIcon />}
                          onClick={handleBack}
                          variant="text"
                          sx={{ display: { xs: "none", sm: "flex" } }}
                        >
                          Previous
                        </Button>
                      )}
                      {activeStep !== 1 && (
                        <Button
                          startIcon={<ChevronLeftRoundedIcon />}
                          onClick={handleBack}
                          variant="outlined"
                          fullWidth
                          sx={{ display: { xs: "flex", sm: "none" } }}
                        >
                          Previous
                        </Button>
                      )}
                      <Button
                        disabled={
                          !shippingAddress?.fullName ||
                          !shippingAddress?.address ||
                          !shippingAddress?.cellPhone ||
                          !shippingAddress?.city ||
                          !shippingAddress?.country ||
                          !shippingAddress?.postalCode
                        }
                        variant="contained"
                        endIcon={<ChevronRightRoundedIcon />}
                        onClick={activeStep === 2 ? handlePayment : handleNext}
                        sx={{ width: { xs: "100%", sm: "fit-content" } }}
                      >
                        {activeStep === steps.length - 1
                          ? "Place order"
                          : "Next"}
                      </Button>
                    </Box>
                  </React.Fragment>
                )}
              </Box>
            </Grid>
          </Grid>
        </Box>
      </Layout>
    </>
  );
}

